14		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
15		checkpointid "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
16		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/paths"
19		"github.com/entireio/cli/cmd/entire/cli/session"
20		"github.com/entireio/cli/cmd/entire/cli/stringutil"
21		"github.com/entireio/cli/cmd/entire/cli/trailers"
22	)
23	
24	const (
25		reviewContextMaxDetailRunes  = 320
26		reviewContextMaxCheckpoints  = 20
27		reviewContextMaxCommitScans  = 200
28		reviewContextCommitSeparator = "\x1e"
29	)
30	
31	type reviewContextSessionMetadataReader interface {
32		ReadSessionMetadata(ctx context.Context, checkpointID checkpointid.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error)
33	}
34	
35	type reviewContextSessionMetadataPromptsReader interface {
36		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID checkpointid.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
37	}
38	
39	func reviewCheckpointContext(ctx context.Context, worktreeRoot string, scopeBaseRef string) string {
40		committed := reviewCommittedCheckpointContext(ctx, worktreeRoot, scopeBaseRef)
41		inProgress := reviewSessionContextForCurrentHead(ctx, worktreeRoot)
42		return joinReviewContextSections(committed, inProgress)
43	}
44	
45	// joinReviewContextSections concatenates non-empty review-context sections
46	// with a blank line between them so each lands as its own paragraph in the
47	// composed agent prompt. Either argument may be empty; when both are empty
48	// the result is empty (and ComposeReviewPrompt skips it cleanly).
49	func joinReviewContextSections(sections ...string) string {
50		nonEmpty := sections[:0]
51		for _, s := range sections {
52			if s != "" {
53				nonEmpty = append(nonEmpty, s)
54			}
55		}
56		return strings.Join(nonEmpty, "\n\n")
57	}
58	
59	// reviewSessionContextForCurrentHead resolves HEAD and delegates to
60	// reviewSessionContext. Kept separate from reviewCheckpointContext so that
61	// in-progress session context is surfaced even when there are no committed
62	// checkpoints in scope (the common case: branch with only uncommitted work).
63	func reviewSessionContextForCurrentHead(ctx context.Context, worktreeRoot string) string {
64		repo, err := gitrepo.OpenPath(worktreeRoot)
65		if err != nil {
66			logging.Debug(ctx, "review session context: open repo", slog.String("error", err.Error()))
67			return ""
68		}
69		defer repo.Close()
70		head, err := repo.Head()
71		if err != nil {
72			logging.Debug(ctx, "review session context: resolve HEAD", slog.String("error", err.Error()))
73			return ""
74		}
75		return reviewSessionContext(ctx, worktreeRoot, head.Hash().String())
76	}
77	
78	// reviewCommittedCheckpointContext renders the "Checkpoint context from
79	// commits in scope:" section. Previously the body of reviewCheckpointContext;
80	// extracted so the parent can compose it with the in-progress session
81	// section.
82	func reviewCommittedCheckpointContext(ctx context.Context, worktreeRoot string, scopeBaseRef string) string {
83		if scopeBaseRef == "" {
84			return ""
85		}
86	
87		messages, commitsTruncated, err := reviewContextCommitMessages(ctx, worktreeRoot, scopeBaseRef, reviewContextMaxCommitScans)
88		if err != nil || len(messages) == 0 {
89			if err != nil {
90				logging.Debug(ctx, "review checkpoint context: list commit messages", slog.String("error", err.Error()))
91			}
92			return ""
93		}
94	
95		repo, err := gitrepo.OpenPath(worktreeRoot)
96		if err != nil {
97			logging.Debug(ctx, "review checkpoint context: open repo", slog.String("error", err.Error()))
98			return ""
99		}
100		defer repo.Close()
101		store := checkpoint.NewGitStore(repo)
102	
103		var lines []string
104		seen := map[checkpointid.CheckpointID]bool{}
105		omittedCheckpoints := 0
106		for _, message := range messages {
107			for _, cpID := range trailers.ParseAllCheckpoints(message) {
108				if seen[cpID] {
109					continue
110				}
111				seen[cpID] = true
112	
113				if len(lines) >= reviewContextMaxCheckpoints {
114					omittedCheckpoints++
115					continue
116				}
117	
118				summary, err := checkpoint.ReadCommittedCheckpoint(ctx, store, cpID)
119				if err != nil {
120					lines = append(lines, fmt.Sprintf("- %s: checkpoint metadata unavailable", cpID))
121					continue
122				}
123				detail := reviewCheckpointDetail(ctx, store, cpID, summary)
124				if detail == "" {
125					detail = "no summary or prompt recorded"
126				}
127				lines = append(lines, fmt.Sprintf("- %s: %s", cpID, detail))
128			}
129		}
130		if len(lines) == 0 {
131			return ""
132		}
133		if omittedCheckpoints > 0 {
134			lines = append(lines, fmt.Sprintf("- ... %d more %s omitted", omittedCheckpoints, reviewContextCheckpointNoun(omittedCheckpoints)))
135		}
136		if commitsTruncated {
137			lines = append(lines, fmt.Sprintf("- ... older commits omitted after scanning latest %d commits", reviewContextMaxCommitScans))
138		}
139	
140		return "Checkpoint context from commits in scope:\n" +
141			strings.Join(lines, "\n") +
142			"\n\nUse `entire explain <id>` for full checkpoint context, or `entire explain <id> --raw-transcript` for raw transcripts."
143	}
144	
145	// reviewSessionContext returns a "In-progress session context (uncommitted):"
146	// block summarising active agent sessions whose work is not yet committed.
147	//
148	// Inclusion criteria — a session qualifies if all of:
149	//   - state.WorktreePath == worktreeRoot (this checkout)
150	//   - state.BaseCommit == headSHA (work since the last commit on this branch)
151	//   - !state.FullyCondensed (still in flight)
152	//   - state.Kind != KindAgentReview (don't include the review agent itself)
153	//
154	// For each qualifying session, render one line:
155	//
156	//	<sessionID[:8]> <agent-name> [(touched: N file(s))] prompt: <latest prompt>
157	//
158	// where latest prompt is read from <worktree>/.entire/metadata/<sessionID>/prompt.txt
159	// (the on-filesystem path lifecycle.go appends to on every turn), passed through
160	// the existing reviewPromptText helper to match the committed-pipeline fallback
161	// format (loops backwards for the newest non-empty prompt, collapses whitespace,
162	// truncates).
163	//
164	// Best-effort: any error path returns "" so the run continues. Sessions whose
165	// prompt.txt is missing or empty are skipped silently.
166	//
167	// Why filesystem-not-shadow-branch: for active sessions prompts are written to
168	// disk at lifecycle.go:294-310 on every turn for mid-turn commit availability,
169	// before SaveStep copies them onto the shadow branch. Filesystem is canonical
170	// for in-progress reads; the shadow-branch copy is only canonical post-condensation.
171	func reviewSessionContext(ctx context.Context, worktreeRoot, headSHA string) string {
172		if worktreeRoot == "" || headSHA == "" {
173			return ""
174		}
175		store, err := session.NewStateStore(ctx)
176		if err != nil {
177			logging.Debug(ctx, "review session context: open state store", slog.String("error", err.Error()))
178			return ""
179		}
180		states, err := store.List(ctx)
181		if err != nil {
182			logging.Debug(ctx, "review session context: list session states", slog.String("error", err.Error()))
183			return ""
184		}
185	
186		// Canonicalise the current worktree path once. State files written by
187		// lifecycle hooks store whatever path the agent process was launched
188		// from, which on macOS frequently differs from `paths.WorktreeRoot`
189		// only by the /var → /private/var symlink. Comparing canonical forms
190		// avoids missing matches that string equality would drop.
191		worktreeCanon := canonicalisePath(worktreeRoot)
192	
193		var lines []string
194		for _, st := range states {
195			if st == nil {
196				continue
197			}
198			if canonicalisePath(st.WorktreePath) != worktreeCanon {
199				continue
200			}
201			if st.BaseCommit != headSHA {
202				continue
203			}
204			if st.FullyCondensed {
205				continue
206			}
207			if st.Kind == session.KindAgentReview {
208				continue
209			}
210			line := formatReviewSessionLine(worktreeRoot, st)
211			if line == "" {
212				continue
213			}
214			lines = append(lines, line)
215		}
216		if len(lines) == 0 {
217			return ""
218		}
219		return "In-progress session context (uncommitted):\n" + strings.Join(lines, "\n")
220	}
221	
222	// canonicalisePath returns the symlink-resolved absolute form of p. Falls
223	// back to p itself when EvalSymlinks fails (e.g., the path doesn't exist
224	// yet) so callers always get a usable comparable value.
225	func canonicalisePath(p string) string {
226		if p == "" {
227			return ""
228		}
229		if resolved, err := filepath.EvalSymlinks(p); err == nil {
230			return resolved
231		}
232		return p
233	}
234	
235	// formatReviewSessionLine renders one entry of the in-progress section.
236	// Returns "" when the session has no prompt content to report.
237	func formatReviewSessionLine(worktreeRoot string, st *session.State) string {
238		promptPath := filepath.Join(worktreeRoot, paths.SessionMetadataDirFromSessionID(st.SessionID), paths.PromptFileName)
239		raw, err := os.ReadFile(promptPath) //nolint:gosec // path constructed from validated session ID + fixed constants
240		if err != nil {
241			return ""
242		}
243		promptText := reviewPromptText(string(raw))
244		if promptText == "" {
245			return ""
246		}
247	
248		short := st.SessionID
249		if len(short) > 8 {
250			short = short[:8]
251		}
252		agentName := string(st.AgentType)
253		if agentName == "" {
254			agentName = "agent"
255		}
256	
257		parts := []string{"  " + short, agentName}
258		if n := len(st.FilesTouched); n > 0 {
259			fileWord := "files"
260			if n == 1 {
261				fileWord = "file"
262			}
263			parts = append(parts, fmt.Sprintf("(touched: %d %s)", n, fileWord))
264		}
265		parts = append(parts, "prompt: "+promptText)
266		return strings.Join(parts, " ")
267	}
268	
269	func reviewCheckpointDetail(
270		ctx context.Context,
271		reader checkpoint.CommittedReader,
272		cpID checkpointid.CheckpointID,
273		summary *checkpoint.CheckpointSummary,
274	) string {
275		sessions := make([]reviewContextSessionDetail, 0, len(summary.Sessions))
276		for i := len(summary.Sessions) - 1; i >= 0; i-- {
277			meta, err := readReviewContextSessionMetadata(ctx, reader, cpID, i)
278			if err != nil || meta == nil || session.Kind(meta.Kind).IsReview() {
279				continue
280			}
281			sessions = append(sessions, reviewContextSessionDetail{
282				index: i,
283			})
284			if text := reviewSummaryText(meta.Summary); text != "" {
285				return "summary: " + text
286			}
287		}
288		for _, sessionDetail := range sessions {
289			prompts, err := readReviewContextSessionPrompts(ctx, reader, cpID, sessionDetail.index)
290			if err == nil {
291				if text := reviewPromptText(prompts); text != "" {
292					return "prompt: " + text
293				}
294			}
295		}
296		return ""
297	}
298	
299	type reviewContextSessionDetail struct {
300		index int
301	}
302	
303	func readReviewContextSessionMetadata(
304		ctx context.Context,
305		reader checkpoint.CommittedReader,
306		cpID checkpointid.CheckpointID,
307		sessionIndex int,
308	) (*checkpoint.CommittedMetadata, error) {
309		if r, ok := reader.(reviewContextSessionMetadataReader); ok {
310			return r.ReadSessionMetadata(ctx, cpID, sessionIndex) //nolint:wrapcheck // Best-effort prompt context.
311		}
312		content, err := reader.ReadSessionContent(ctx, cpID, sessionIndex)
313		if err != nil {
314			return nil, err //nolint:wrapcheck // Best-effort prompt context.
315		}
316		if content == nil {
317			return nil, errors.New("session content is nil")
318		}
319		return &content.Metadata, nil
320	}
321	
322	func readReviewContextSessionPrompts(
323		ctx context.Context,
324		reader checkpoint.CommittedReader,
325		cpID checkpointid.CheckpointID,
326		sessionIndex int,
327	) (string, error) {
328		if r, ok := reader.(reviewContextSessionMetadataPromptsReader); ok {
329			content, err := r.ReadSessionMetadataAndPrompts(ctx, cpID, sessionIndex)
330			if err == nil {
331				if content == nil {
332					return "", errors.New("session content is nil")
333				}
334				return content.Prompts, nil
335			}
336			if !errors.Is(err, checkpoint.ErrCheckpointNotFound) {
337				return "", err //nolint:wrapcheck // Best-effort prompt context.
338			}
339		}
340		content, err := reader.ReadSessionContent(ctx, cpID, sessionIndex)
341		if err != nil {
342			return "", err //nolint:wrapcheck // Best-effort prompt context.
343		}
344		if content == nil {
345			return "", errors.New("session content is nil")
346		}
347		return content.Prompts, nil
348	}
349	
350	func reviewSummaryText(summary *checkpoint.Summary) string {
351		if summary == nil {
352			return ""
353		}
354		parts := []string{
355			stringutil.CollapseWhitespace(summary.Intent),
356			stringutil.CollapseWhitespace(summary.Outcome),
357		}
358		for _, item := range summary.OpenItems {
359			if text := stringutil.CollapseWhitespace(item); text != "" {
360				parts = append(parts, "open: "+text)
361				break
362			}
363		}
364		return truncateReviewContextText(strings.Join(nonEmptyReviewContextParts(parts), "; "))
365	}
366	
367	func reviewPromptText(promptContent string) string {
368		prompts := checkpoint.SplitPromptContent(promptContent)
369		for i := len(prompts) - 1; i >= 0; i-- {
370			if text := stringutil.CollapseWhitespace(prompts[i]); text != "" {
371				return truncateReviewContextText(text)
372			}
373		}
374		return ""
375	}
376	
377	func nonEmptyReviewContextParts(parts []string) []string {
378		result := parts[:0]
379		for _, part := range parts {
380			if part != "" {
381				result = append(result, part)
382			}
383		}
384		return result
385	}
386	
387	func truncateReviewContextText(value string) string {
388		runes := []rune(value)
389		if len(runes) <= reviewContextMaxDetailRunes {
390			return value
391		}
392		return strings.TrimSpace(string(runes[:reviewContextMaxDetailRunes-3])) + "..."
393	}
394	
395	func reviewContextCheckpointNoun(count int) string {
396		if count == 1 {
397			return "checkpoint"
398		}
399		return "checkpoints"
400	}
401	
402	func reviewContextCommitMessages(ctx context.Context, repoRoot string, scopeBaseRef string, maxCommits int) ([]string, bool, error) {
403		if maxCommits <= 0 {
404			return nil, false, nil
405		}
406		records, err := reviewContextGitRecords(
407			ctx,
408			repoRoot,
409			"log",
410			"--max-count="+strconv.Itoa(maxCommits+1),
411			"--format="+reviewContextCommitSeparator+"%B",
412			scopeBaseRef+"..HEAD",
413		)
414		if err != nil {
415			return nil, false, err
416		}
417		truncated := len(records) > maxCommits
418		if truncated {
419			records = records[:maxCommits]
420		}
421		return records, truncated, nil
422	}
423	
424	func reviewContextGitRecords(ctx context.Context, repoRoot string, args ...string) ([]string, error) {
425		full := append([]string{"-C", repoRoot}, args...)
426		output, err := exec.CommandContext(ctx, "git", full...).Output()
427		if err != nil {
428			return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
429		}
430		parts := strings.Split(string(output), reviewContextCommitSeparator)
431		records := make([]string, 0, len(parts))
432		for _, part := range parts {
433			trimmed := strings.TrimSpace(part)
434			if trimmed != "" {
435				records = append(records, trimmed)
436			}
437		}
438		return records, nil
439	}
