func writeReviewContextCheckpointsVersion(t *testing.T, repoRoot, version string) {
	t.Helper()
	entireDir := filepath.Join(repoRoot, ".entire")
	if err := os.MkdirAll(entireDir, 0o750); err != nil {
		t.Fatalf("create .entire dir: %v", err)
	}
	body := fmt.Sprintf(`{"enabled":true,"strategy_options":{"checkpoints_version":%q}}`+"\n", version)
	if err := os.WriteFile(filepath.Join(entireDir, paths.SettingsFileName), []byte(body), 0o600); err != nil {
		t.Fatalf("write settings: %v", err)
	}
}

