// TestReviewCheckpointContext_ReadsV11CustomRefWhenOptedIn proves the review
// committed-context read resolves against the v1.1 custom ref when
// checkpoints_version "1.1" is opted in, and against the v1 branch otherwise.
// No t.Parallel: relies on t.Chdir for settings (checkpoints_version) resolution.
func TestReviewCheckpointContext_ReadsV11CustomRefWhenOptedIn(t *testing.T) {
	repoRoot := newReviewContextRepo(t)
	t.Chdir(repoRoot)

	const cpID = "c1d2e3f4a5b6"
	writeReviewContextCheckpointCustomRefOnly(t, repoRoot, cpID, reviewContextCheckpointOptions{
		filesTouched: []string{"v11.go"},
		agentType:    agent.AgentTypeClaudeCode,
		summary: &checkpoint.Summary{
			Intent:  "v1.1-only checkpoint",
			Outcome: "read via custom ref",
		},
	})
	commitReviewContextChange(t, repoRoot, "v11.go", "v11\n", "v11 change", "Entire-Checkpoint: "+cpID)

	const wantDetail = "summary: v1.1-only checkpoint; read via custom ref"

	// Without opt-in, reads resolve against the v1 branch (which no longer holds
	// the checkpoint), so its detail is absent.
	if got := reviewCheckpointContext(context.Background(), repoRoot, "master"); strings.Contains(got, wantDetail) {
		t.Fatalf("checkpoint detail leaked without v1.1 opt-in:\n%s", got)
	}

	// Opt into checkpoints_version 1.1: reads resolve against the custom ref and
	// surface the checkpoint.
	writeReviewContextCheckpointsVersion(t, repoRoot, "1.1")
	got := reviewCheckpointContext(context.Background(), repoRoot, "master")
	if !strings.Contains(got, wantDetail) {
		t.Fatalf("checkpoint detail missing with v1.1 opt-in:\n%s", got)
	}
}

